import torch

def sinkhorn(C, a, b, eps=0.05, iters=20):
    K = torch.exp(-C / eps)
    u = torch.ones_like(a)
    for _ in range(iters):
        v = b / (K.t() @ u + 1e-8)
        u = a / (K @ v + 1e-8)
    return torch.diag(u) @ K @ torch.diag(v)

def bsearch(a, x):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == x:
            return mid
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

import torch

def reflow_loss(v_theta, x0, x1, t):
    # x0: noise, x1: teacher endpoint, t: [B, 1, ...]
    xt = (1 - t) * x0 + t * x1
    target = x1 - x0
    return ((v_theta(xt, t) - target) ** 2).mean()

import torch

def sago(outputs_per_variant, eps=1e-6):
    # outputs_per_variant: [V, B, C] 同一批样本在 V 种表述下的 logits
    p = torch.softmax(outputs_per_variant, dim=-1)
    conf = p.max(dim=-1).values            # [V, B]
    return (conf.std(dim=0) / (conf.mean(dim=0).abs() + eps)).mean()
